+export async function handleJobEvent(event: JobEvent): Promise<void> {
+  // Deduplicate by jobId to handle retries
+  const alreadyProcessed = await isJobProcessed(event.jobId);
+  if (alreadyProcessed) {
+    console.log(`Job ${event.jobId} already processed, skipping`);
+    return;
+  }
+
+  console.log(`Processing job ${event.jobId} created at ${event.createdAt}`);
+  const payload = JSON.parse(event.payload);
+
+  // Route to appropriate handler based on payload
+  if (payload.type === "email") {
+    await sendEmail(payload);
+  } else if (payload.type === "sms") {
+    await sendSms(payload);
+  } else {
+    throw new Error(`Unknown job type: ${payload.type}`);
+  }
