+import { PoolClient } from "pg";
+
+export interface JobEvent {
+  type: "job.created";
+  jobId: string;
+  payload: string;
+  createdAt: string;
+}
+
+type NotificationBackend = {
+  publish: (event: JobEvent) => Promise<void>;
+};
+
+let backend: NotificationBackend | null = null;
+
+export const setNotificationBackend = (b: NotificationBackend): void => {
+  backend = b;
+};
+
+export const addJobEventToOutbox = async (
+  client: PoolClient,
+  jobId: string,
+  payload: string,
+): Promise<void> => {
+  await client.query(
+    "INSERT INTO outbox (event_type, job_id, payload) VALUES ($1, $2, $3)",
+    ["job.created", jobId, payload],
+  );
+};
+
+export const drainOutbox = async (): Promise<void> => {
+  if (!backend) return;
+
+  const { pool } = await import("./pool.ts");
+  const result = await pool.query(
+    "SELECT id, job_id, payload FROM outbox ORDER BY created_at LIMIT 100",
+  );
+
+  for (const row of result.rows) {
+    try {
+      const event: JobEvent = {
+        type: "job.created",
+        jobId: row.job_id,
+        payload: row.payload,
+        createdAt: new Date().toISOString(),
+      };
+      await backend.publish(event);
+      await pool.query("DELETE FROM outbox WHERE id = $1", [row.id]);
+    } catch (err) {
+      console.error(`Failed to publish outbox event ${row.id}:`, err);
+    }
+  }
+};
+
+export const createWebhookBackend = (webhookUrl: string): NotificationBackend => {
+  return {
+    publish: async (event: JobEvent) => {
+      const response = await fetch(webhookUrl, {
+        method: "POST",
+        headers: { "Content-Type": "application/json" },
+        body: JSON.stringify(event),
+      });
+      if (!response.ok) {
+        throw new Error(`Webhook failed: ${response.status} ${response.statusText}`);
+      }
+    },
+  };
+};
