+import { drainOutbox } from "./notifications.ts";
+
+const DRAIN_INTERVAL_MS = 5000;
+
+export const runOutboxService = async (): Promise<void> => {
+  for (;;) {
+    try {
+      await drainOutbox();
+    } catch (err) {
+      console.error("Outbox drain failed:", err);
+    }
+    await new Promise((resolve) => setTimeout(resolve, DRAIN_INTERVAL_MS));
+  }
+};
